import sys

def find_beautiful_sequence(k, q):
    if k > len(q):
        return "NO"

    used_chars = set()
    result = []
    i = 0

    while i < len(q) and len(result) < k:
        char = q[i]
        if char not in used_chars:
            used_chars.add(char)
            start = i
            while i < len(q) and q[i] == char:
                i += 1
            result.append(q[start:i])
        else:
            i += 1

    if len(result) < k:
        return "NO"

    return "YES\n" + "\n".join(result)

input = sys.stdin.read().splitlines()
k = int(input[0])
q = input[1]
print(find_beautiful_sequence(k, q))
